package com.ultras.bans.service;
import com.ultras.bans.ULTRASBansPlugin; import com.ultras.bans.database.Database; import com.ultras.bans.model.PlayerRecord; import org.bukkit.entity.Player; import java.net.InetSocketAddress; import java.time.Instant; import java.util.*;
public final class PlayerService { private final ULTRASBansPlugin plugin; private final Database db; public PlayerService(ULTRASBansPlugin p,Database d){plugin=p;db=d;} public void track(Player p,boolean joining){ InetSocketAddress a=p.getAddress(); String ip=a==null?"":a.getAddress().getHostAddress(); String platform="Java"; try{Class.forName("org.geysermc.floodgate.api.FloodgateApi"); var api=Class.forName("org.geysermc.floodgate.api.FloodgateApi").getMethod("getInstance").invoke(null); if(api!=null && (Boolean)api.getClass().getMethod("isFloodgatePlayer",java.util.UUID.class).invoke(api,p.getUniqueId())) platform="Bedrock";}catch(Throwable ignored){} String loc=p.getWorld().getName()+" "+p.getLocation().getBlockX()+","+p.getLocation().getBlockY()+","+p.getLocation().getBlockZ(); Instant now=Instant.now(); db.upsertPlayer(new PlayerRecord(p.getUniqueId(),p.getName(),ip,platform,"default",p.isOp(),plugin.serverId(),p.getWorld().getName(),loc,now,joining?now:null,joining?null:now)); } public String platform(Player p){try{Class.forName("org.geysermc.floodgate.api.FloodgateApi"); var api=Class.forName("org.geysermc.floodgate.api.FloodgateApi").getMethod("getInstance").invoke(null); return api!=null&&(Boolean)api.getClass().getMethod("isFloodgatePlayer",java.util.UUID.class).invoke(api,p.getUniqueId())?"Bedrock":"Java";}catch(Throwable e){return "Java";}} public Player find(String s){Player p=plugin.getServer().getPlayerExact(s);if(p!=null)return p;try{return plugin.getServer().getPlayer(UUID.fromString(s));}catch(Exception ignored){}return null;}}
